package com.saurabh.paymentgateway.domain;
import jakarta.persistence.*;import org.hibernate.annotations.JdbcTypeCode;import org.hibernate.type.SqlTypes;import java.time.Instant;import java.util.Map;import java.util.UUID;
@Entity @Table(name="authorization_events") public class AuthorizationEvent { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(nullable=false) private UUID authorizationId; @Column(nullable=false) private String eventType; @Column(nullable=false) private String status; @Column(nullable=false) private Instant occurredAt; @JdbcTypeCode(SqlTypes.JSON) @Column(nullable=false,columnDefinition="jsonb") private Map<String,Object> metadata; protected AuthorizationEvent(){} public AuthorizationEvent(UUID authId,String type,String status,Map<String,Object> metadata){this.authorizationId=authId;this.eventType=type;this.status=status;this.occurredAt=Instant.now();this.metadata=metadata;} }
